import { paths } from '~/paths'
import { MethodLink } from '~/ui/parts/MethodLink'
import type { MethodLinkOptionProp } from '~/ui/parts/MethodLink'

import thumbnailM from './thumbnail.mp4'
import thumbnailP from './thumbnail.jpg'

import { name } from './name'

/** @jsxImportSource @emotion/react */
//import { css } from '@emotion/react'


type Prop = MethodLinkOptionProp & {
  openDrawer: (kind: string, name: string) => () => void
}
export default function Link(prop: Prop) {
  const { openDrawer, ...othreProp  } = prop;
  // Videoのループ再生時の例外問題で動画がちらつくことがあるため、写真を裏に表示しておくことでちらつき防止とする。（本来写真は不要）
  return (
    <MethodLink title='カム機構(トグル機構)' thumbnailVideo={thumbnailM} thumbnailImage={thumbnailP} openDrawer={openDrawer(paths.block.method.lego.key, name)} {...othreProp} />
  )
}


